// Travel poster for LUMARIS, a place that isn't there (Node 22, standard
// library only). The poster image is embedded below as base64: it was drawn
// locally with Pillow by gen_poster.py (also in this repo) — a dusk bay where
// the lagoon glows turquoise, a striped lighthouse on the right cliff
// sweeping its beam across the sunset, white cliff-houses on the left,
// sailboats with lanterns, and the invented place's name set large in the
// sky: LUMARIS, "THE GLOWING SHORE", "WHERE THE SEA LIGHTS THE NIGHT".
// The program decodes the embedded PNG and writes it, byte for byte, to the
// output directory the grader gives it: no network, no randomness, so two
// runs write identical bytes. The PNG is 1024x1024 and 50,639 bytes, well
// under the 1 MiB gate.
//
// Outside the grader, MAKEFUN_OUTPUT_DIR stands in for /output:
//   mkdir -p out && MAKEFUN_OUTPUT_DIR=out node main.ts

import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

// entry.png (1024x1024), base64. Generated by gen_poster.py; this constant
// is the exact bytes of that file.
const PNG_B64 = '';

const outDir = process.env.MAKEFUN_OUTPUT_DIR ?? '/output';
mkdirSync(outDir, { recursive: true });
writeFileSync(join(outDir, 'entry.png'), Buffer.from(PNG_B64, 'base64'));
